// The browser link v2 against fixtures/vectors/symbiont_link.json (generated by
// the Python reference): BLAKE2b, crypto_kx, the signed handshake, AES-GCM
// records and every packet -- produced here byte for byte, and refused here
// with the same field path and rule as in Python.
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { test } from 'node:test';

import { type CanonObject, canonicalText, fromHex, parseLossless, toHex } from '../src/core/canon.ts';
import { WebCryptoSigner } from '../src/core/ed25519.ts';
import { blake2b512 } from '../src/net/blake2b.ts';
import { KxError, clientSessionKeyBytes, clientSessionKeys, generateKxKeyPair, kxKeyPairFromSecretForTests } from '../src/net/kx.ts';
import * as la from '../src/net/linkauth.ts';
import * as pk from '../src/net/packets.ts';
import { MAX_PLAINTEXT, MAX_RECORD, RecordError, RecordLayer } from '../src/net/records.ts';

const V = JSON.parse(readFileSync(new URL('../../fixtures/vectors/symbiont_link.json', import.meta.url), 'utf8'));
const HS = V.handshake;
const KX = V.kx;

const clientPair = () => kxKeyPairFromSecretForTests(fromHex(KX.client_secret_hex), fromHex(KX.client_public_hex));

/** The node's side of the vectors' link, built from the server's raw keys (tests only). */
async function nodeLayer(): Promise<RecordLayer> {
  const [crx, ctx] = [fromHex(KX.client_rx_hex), fromHex(KX.client_tx_hex)];
  const rx = await crypto.subtle.importKey('raw', ctx, { name: 'AES-GCM' }, false, ['decrypt']);
  const tx = await crypto.subtle.importKey('raw', crx, { name: 'AES-GCM' }, false, ['encrypt']);
  return new RecordLayer({ rx, tx }, HS.link);
}

async function pageLayer(): Promise<RecordLayer> {
  return new RecordLayer(await clientSessionKeys(await clientPair(), fromHex(KX.server_public_hex)), HS.link);
}

async function sealOne(layer: RecordLayer, plain: Uint8Array): Promise<Uint8Array> {
  let out: Uint8Array | null = null;
  await layer.sealAndSend(plain, (r) => {
    out = r;
  });
  return out!;
}

test('BLAKE2b-512 for 0..257 bytes and the crypto_kx shape', () => {
  for (const c of V.blake2b_512) assert.equal(toHex(blake2b512(fromHex(c.input_hex))), c.digest_hex);
});

test('crypto_kx: the page derives the very keys PyNaCl does, and refuses low-order keys', async () => {
  const [rx, tx] = await clientSessionKeyBytes(await clientPair(), fromHex(KX.server_public_hex));
  assert.equal(toHex(rx), KX.client_rx_hex);
  assert.equal(toHex(tx), KX.client_tx_hex);
  for (const bad of KX.refused_peer_public_hex) {
    await assert.rejects(clientSessionKeys(await generateKxKeyPair(), fromHex(bad)), KxError);
  }
  const fresh = await generateKxKeyPair();
  assert.equal(fresh.publicKey.length, 32);
  assert.equal(fresh.privateKey.extractable, false);
});

test('records: sealed byte for byte, opened in order, both ways', async () => {
  const page = await pageLayer();
  const node = await nodeLayer();
  for (const c of V.records.page_to_node) {
    assert.equal(toHex(await sealOne(page, fromHex(c.plaintext_hex))), c.record_hex);
    assert.equal(toHex(await node.open(fromHex(c.record_hex))), c.plaintext_hex);
  }
  for (const c of V.records.node_to_page) assert.equal(toHex(await page.open(fromHex(c.record_hex))), c.plaintext_hex);
  assert.equal(V.records.max_plaintext, MAX_PLAINTEXT);
  assert.equal(V.records.max_record, MAX_RECORD);
  const big = await sealOne(page, new Uint8Array(MAX_PLAINTEXT).fill(0x79));
  assert.equal(big.length, MAX_RECORD);
  const d = toHex(new Uint8Array(await crypto.subtle.digest('SHA-256', Uint8Array.from(big))));
  assert.equal(d, V.records.largest.record_sha256);
});

test('records: every reject case closes the receiver for good', async () => {
  for (const c of V.records.rejects) {
    const node = await nodeLayer();
    const recs = c.records_hex.map(fromHex);
    for (const r of recs.slice(0, -1)) await node.open(r);
    await assert.rejects(node.open(recs.at(-1)), RecordError, c.name);
    assert.ok(node.closed, c.name);
    await assert.rejects(node.open(fromHex(V.records.page_to_node[0].record_hex)), RecordError);
  }
});

test('records: oversize is refused before a seq is spent; a failed send closes the layer', async () => {
  const page = await pageLayer();
  await assert.rejects(page.sealAndSend(new Uint8Array(MAX_PLAINTEXT + 1), () => {}), RecordError);
  assert.equal(page.closed, null);
  assert.equal(toHex(await sealOne(page, fromHex(V.records.page_to_node[0].plaintext_hex))), V.records.page_to_node[0].record_hex);
  await assert.rejects(page.sealAndSend(new Uint8Array(1), () => Promise.reject(new Error('channel closed'))), RecordError);
  assert.ok(page.closed);
  await assert.rejects(page.sealAndSend(new Uint8Array(1), () => {}), RecordError);
});

test('records: concurrent sends go out in seq order even when encryption finishes out of order', async () => {
  const page = await pageLayer();
  const node = await nodeLayer();
  const wire: Uint8Array[] = [];
  const slow = [30, 0, 15, 5, 0, 25, 10, 0];
  await Promise.all(
    slow.map((ms, i) =>
      page.sealAndSend(new TextEncoder().encode(`m${i}`), async (r) => {
        await new Promise((res) => setTimeout(res, ms));
        wire.push(r);
      }),
    ),
  );
  const seqs = wire.map((r) => Number(new DataView(r.buffer, r.byteOffset).getBigUint64(1)));
  assert.deepEqual(seqs, [0, 1, 2, 3, 4, 5, 6, 7]);
  const got = [];
  for (const r of wire) got.push(new TextDecoder().decode(await node.open(r)));
  assert.deepEqual(got, slow.map((_, i) => `m${i}`));
});

test('records: zeroize drops the keys', async () => {
  const page = await pageLayer();
  page.zeroize('the link went away');
  assert.equal(page.closed, 'the link went away');
  await assert.rejects(page.sealAndSend(new Uint8Array(1), () => {}), RecordError);
  await assert.rejects(page.open(fromHex(V.records.node_to_page[0].record_hex)), RecordError);
});

test('handshake: the link digest, INIT and ACCEPT are the Python bytes', async () => {
  const app = await WebCryptoSigner.fromSeed(fromHex(HS.app.seed_hex));
  const node = await WebCryptoSigner.fromSeed(fromHex(HS.node.seed_hex));
  const nb = parseLossless(HS.node_binding) as CanonObject;
  const pb = parseLossless(HS.page_binding) as CanonObject;
  assert.equal(await la.linkDigest(nb, pb), HS.link);
  assert.notEqual(await la.linkDigest(pb as never, nb as never).catch(() => 'x'), HS.link);
  const init = await la.createHandshakeInit(app, { clientPublic: fromHex(KX.client_public_hex), link: HS.link, lang: 'zh', timestampMs: HS.now_ms });
  assert.equal(canonicalText(init), HS.init);
  const accept = await la.createHandshakeAccept(node, {
    serverPublic: fromHex(KX.server_public_hex),
    clientPublic: fromHex(KX.client_public_hex),
    link: HS.link,
    timestampMs: HS.now_ms,
  });
  assert.equal(canonicalText(accept), HS.accept);
  const r = await la.verifyHandshakeAccept(parseLossless(HS.accept), {
    nodeDid: HS.node.did,
    clientPublic: fromHex(KX.client_public_hex),
    link: HS.link,
    nowMs: HS.now_ms,
  });
  assert.ok(r.ok, r.reason ?? '');
  assert.equal(toHex(r.pubkey!), KX.server_public_hex);
  const i = await la.verifyHandshakeInit(parseLossless(HS.init), { appDid: HS.app.did, link: HS.link, nowMs: HS.now_ms });
  assert.ok(i.ok && i.lang === 'zh');
});

test('handshake: refused with the same reasons as Python', async () => {
  for (const c of HS.init_rejects) {
    const r = await la.verifyHandshakeInit(parseLossless(c.text), { appDid: HS.app.did, link: HS.link, nowMs: HS.now_ms });
    assert.deepEqual([r.ok, r.reason], [false, c.reason], c.name);
  }
  for (const c of HS.accept_rejects) {
    const r = await la.verifyHandshakeAccept(parseLossless(c.text), {
      nodeDid: HS.node.did,
      clientPublic: fromHex(KX.client_public_hex),
      link: HS.link,
      nowMs: HS.now_ms,
    });
    assert.deepEqual([r.ok, r.reason], [false, c.reason], c.name);
  }
});

test('packets: the same limits; good ones round-trip; bad ones fail at the same path and rule', () => {
  assert.deepEqual(V.packets.limits, { ...pk.LIMITS });
  assert.deepEqual(V.packets.reflection_sets, { questions: [...pk.QUESTIONS], paths: [...pk.PATHS], saw_facts: [...pk.SAW_FACTS] });
  assert.equal(V.packets.max_packet_bytes, pk.MAX_PACKET_BYTES);
  const enc = new TextEncoder();
  for (const c of V.packets.good) {
    const p = pk.decode(enc.encode(c.text));
    assert.equal(canonicalText(p), c.text, c.name);
    assert.equal(new TextDecoder().decode(pk.encode(p)), c.text, c.name);
  }
  for (const c of V.packets.bad) {
    assert.throws(
      () => pk.decode(enc.encode(c.text)),
      (e: unknown) => e instanceof pk.PacketError && e.path === c.path && e.rule === c.rule,
      `${c.name}: expected ${c.path}: ${c.rule}`,
    );
  }
  for (const c of V.packets.not_canonical) assert.throws(() => pk.decode(enc.encode(c.text)), pk.PacketError, c.name);
  assert.throws(() => pk.decode(new Uint8Array([0xff, 0xfe])), pk.PacketError);
  assert.throws(() => pk.decode(enc.encode(V.packets.good[0].text), 'to-page'), /wrong direction/);
});

test('packets: a refusal never quotes the value', () => {
  try {
    pk.validate({ type: 'ADD_GOAL', goal_id: 'g-1', intent: 'my secret words '.repeat(200) });
    assert.fail('accepted');
  } catch (e) {
    assert.ok(e instanceof pk.PacketError);
    assert.ok(!String(e.message).includes('secret'));
  }
});
